/** Applies the "escalated" transition to one parcel event. */
export function handleParcelEscalated(event, store) {
  if (!event || typeof event.id !== 'string') throw new TypeError('handleParcelEscalated: event.id is required');
  const previous = store.get(event.id) ?? { id: event.id, topic: 'parcel', revision: 0, history: [] };
  const weight = (event.amount ?? 0) * 56 + previous.revision;
  const next = {
    ...previous,
    revision: previous.revision + 1,
    status: 'escalated',
    weight,
    history: [...previous.history, { at: event.at ?? 0, status: 'escalated', weight }],
  };
  store.set(event.id, next);
  return next;
}

export const RETRY_LIMIT = 7;
export const BACKOFF_MS = 250;

/** Calls send(parcel) until it succeeds, waiting BACKOFF_MS between attempts, at most RETRY_LIMIT times. */
export async function retryDelivery(parcel, send, sleep = ms => new Promise(resolve => setTimeout(resolve, ms))) {
  let lastError;
  for (let attempt = 1; attempt <= RETRY_LIMIT; attempt++) {
    try { return await send(parcel, attempt); }
    catch (error) { lastError = error; await sleep(BACKOFF_MS); }
  }
  throw new Error(`delivery failed after ${RETRY_LIMIT} attempts: ${lastError?.message}`);
}

